/*
 * Zairenkai's mascot, from the owner's artwork: one pose per state
 * (art/mascot/<state>.png), each animated as a Lottie
 * (res/raw/mascot_<state>.json, generated by tools/lottie/gen_mascot.py, with
 * the pose's layers embedded so it works offline).
 *
 * State changes cross-fade between poses; the first appearance pops in with a
 * spring. Animations loop seamlessly. With "Remove animations" (or
 * [MascotState.IDLE] under reduced motion) the pose is shown still. While a
 * composition loads, or if it fails, a still image of the mascot holds the
 * space, so the layout never jumps.
 * Copyright (C) 2026 FebriCahyaa
 */
package com.zairenkai.app.ui.mascot

import androidx.annotation.RawRes
import androidx.compose.animation.Crossfade
import androidx.compose.animation.core.Animatable
import androidx.compose.animation.core.Spring
import androidx.compose.animation.core.spring
import androidx.compose.animation.core.tween
import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.size
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.remember
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.graphicsLayer
import androidx.compose.ui.res.painterResource
import androidx.compose.ui.semantics.clearAndSetSemantics
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import com.airbnb.lottie.compose.LottieAnimation
import com.airbnb.lottie.compose.LottieCompositionSpec
import com.airbnb.lottie.compose.LottieConstants
import com.airbnb.lottie.compose.animateLottieCompositionAsState
import com.airbnb.lottie.compose.rememberLottieComposition
import com.zairenkai.app.R
import com.zairenkai.app.ui.onboarding.reducedMotion

/** What the mascot is doing. Driven by real setup state, never by a timer. */
enum class MascotState(@RawRes val anim: Int) {
    /** Open arms, the "!" calling out, hearts: the welcome page. */
    WELCOME(R.raw.mascot_welcome),

    /** Peers through the magnifier while crystals sparkle: a check is running. */
    INSPECTING(R.raw.mascot_inspecting),

    /** Thumbs up with a happy hop: the checks really passed. */
    READY(R.raw.mascot_ready),

    /** Startled, the warning sign flashing: something needs attention. */
    WARNING(R.raw.mascot_warning),

    /** Jumps with stars and confetti: setup really completed. */
    CELEBRATING(R.raw.mascot_celebrating),

    /** Calm, breathing softly. */
    IDLE(R.raw.mascot_idle),
}

/** The state for the setup check: inspecting until every probe answered, then ready or warning. */
fun checkMascotState(settled: Boolean, allOk: Boolean): MascotState = when {
    !settled -> MascotState.INSPECTING
    allOk -> MascotState.READY
    else -> MascotState.WARNING
}

/** Decorative: screen readers get the same meaning from the step's text. */
@Composable
fun Mascot(state: MascotState, modifier: Modifier = Modifier, size: Dp = 200.dp) {
    val still = reducedMotion()
    val pop = remember { Animatable(if (still) 1f else 0.82f) }
    LaunchedEffect(Unit) { if (!still) pop.animateTo(1f, spring(dampingRatio = 0.5f, stiffness = Spring.StiffnessMediumLow)) }
    Box(
        modifier
            .size(size)
            .clearAndSetSemantics {}
            .graphicsLayer {
                scaleX = pop.value
                scaleY = pop.value
                alpha = ((pop.value - 0.82f) / 0.18f).coerceIn(0f, 1f).let { if (still) 1f else 0.25f + 0.75f * it }
            },
    ) {
        Crossfade(targetState = state, animationSpec = tween(320), label = "pose") { s -> Pose(s, still) }
    }
}

@Composable
private fun Pose(state: MascotState, still: Boolean) {
    val result = rememberLottieComposition(LottieCompositionSpec.RawRes(state.anim))
    val composition = result.value
    val progress by animateLottieCompositionAsState(composition, iterations = LottieConstants.IterateForever, isPlaying = !still)
    if (composition == null) {
        // Loading (or failed): a still of the mascot keeps the space.
        Image(painterResource(R.drawable.mascot_fallback), null, Modifier.fillMaxSize(), alignment = Alignment.Center)
    } else {
        LottieAnimation(composition, progress = { if (still) 0f else progress }, modifier = Modifier.fillMaxSize())
    }
}
